{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Docetaxel, a complex polycyclic diterpenoid with multiple polar groups, has an absolute oral bioavailability of about 8% in humans, directly supporting low F for structurally similar complex, polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Fluticasone, a corticosteroid with a ketone and hydroxyl groups, has negligible (<1%) oral bioavailability via gastrointestinal absorption due to extensive first-pass metabolism; the query shares a corticosteroid-like core and multiple hydroxyls.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Danoprevir, a large complex molecule, has an absolute oral bioavailability of only 1.15% without ritonavir, illustrating that complex, metabolically labile structures can have very low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Aneortave desacetate, a steroid, has low oral bioavailability in humans, providing direct steroid-scaffold evidence that the query's steroid-like structure is likely to have low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Docetaxel's low absolute oral bioavailability is attributed to hepatic and intestinal first-pass extraction via CYP3A; the query's multiple hydroxyls and steroid framework are similarly prone to extensive first-pass metabolism.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly hydroxylated, steroid-like molecule. All high-transfer experimental analogues—docetaxel, fluticasone, mometasone, anecortave, danoprevir, oridonin, and andrographolide—show low oral bioavailability, mostly below 10%, due to poor permeability, efflux, and first-pass metabolism. The weight of direct human F measurements strongly supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "No human pharmacokinetic data are available for the query.",
    "No query-specific permeability, P-glycoprotein efflux, or CYP metabolism data are provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

